    def report_pm_counter(self, id, value, result: str) -> None:
        """Keyword to report PM counter result.

        :param string  id:       PM Counter ID
        :param integer value:    PM Counter value
        :param string  result:   PM Counter result. Supported values: Passed, Failed.

        .. note::
            PM counters are not reported immediately.
            PM counters will be read by ``ute_reporting_portal`` script and added to the Robot report.
        """
        value = int(value)
        if not isinstance(id, str):
            raise WrongDataFormat(
                f"Wrong id format. The format should be string, not {type(id)}"
            )
        if result.lower() != "passed" and result.lower() != "failed":
            raise WrongDataFormat(
                f"Wrong result format. Supported values are: Passed or Failed not {result}"
            )
        logger.info(
            f"Reported PM Counter: ID={id}, VALUE={value}, RESULT={result.capitalize()}"
        )

    def report_enb_hardware_configuration(self, configuration) -> None:
        """Keyword to report eNB configuration.

        :param string configuration: eNB configuration.

        .. note::
            eNB configuration is not reported immediately.
            eNB configuration will be read by ``ute_reporting_portal`` script and added to the Robot report.
        """
        if not isinstance(configuration, str):
            raise WrongDataFormat(
                "Wrong configuration format. "
                f"The format should be string, not {type(configuration)}"
            )
        logger.info(f"Reported eNB configuration: {configuration}")

    def log_to_reporting_portal(self, message) -> None:
        """Keyword to log additional information for keyword.

        :param string message: eNB configuration.

        .. note::
            additional information is not reported immediately.
            additional information will be read by ``ute_reporting_portal`` script and added to the Robot report.
        """
        if not isinstance(message, str):
            raise WrongDataFormat(
                "Wrong configuration format. "
                f"The format should be string, not {type(message)}"
            )
        logger.info(f"Additional info: {message}")

    def backup_config(self, product_type=None, load_prefix=None, log_level=None) -> None:
        """Keyword to run backup action for reporting portal.

        :param string product_type: Type of product ['wmp', 'dcm']
        :param string load_prefix:  Prefix for the location
        :param string log_level:    Set if 'debug' level needed instead of 'info'

        .. note::
            additional information is not reported immediately.
            additional information will be read by ``ute_reporting_portal`` script and added to the Robot report.
        """
        if product_type and not isinstance(product_type, str):
            raise WrongDataFormat(
                "Wrong product_type format. "
                f"The format should be string, not {type(product_type)}"
            )
        if load_prefix and not isinstance(load_prefix, str):
            raise WrongDataFormat(
                "Wrong load_prefix format. "
                f"The format should be string, not {type(load_prefix)}"
            )
        enb = EnbUtil()
        enb.backup_config(product_type, load_prefix, log_level)

