    def report_kpi_results(  # noqa: C901
            self,
            target: Optional[str] = None,
            name: Optional[str] = None,
            visible_to_db: Optional[str] = None,
            value: Optional[str] = None,
            kpi_type: Optional[str] = None,
            description: Optional[str] = None,
            category: Optional[str] = None,
            unit: Optional[str] = None,
            kpi_id: Optional[str] = None,
            variant: Optional[str] = None,
            source: Optional[str] = None,
            entity_id: Optional[str] = None,
            comparison_operator: Optional[str] = None,
    ) -> None:
        """Keyword to report kpi results.

        There are two-way of reporting KPIs.

        1. Report any KPI - name of KPI is not validated anywhere, you can pass free text.
            Required parameters:
                target, name, visible_to_db, value, kpi_type, description, category, unit
        2. Report KPI defined in external source - eg OAMKPI sharepoint table.
            https://nokia.sharepoint.com/sites/SRANOSPDZLT/Lists/Unique%20KPI%20ID/AllItems.aspx?skipSignal=true
            This solution has fewer parameters because most of KPI information like unit, category, etc. is
            fulfilling automatically by ReP in kpi report(based on source table).
            Required parameters:
                kpi_id, value, target, variant, source

        :param string  target:          KPI target
        :param string  name:            KPI name
        :param string  visible_to_db:   defines visibility for db
        :param string  value:           KPI value
        :param string  kpi_type:        KPI type
        :param string  description:     KPI description
        :param string  category:        KPI category
        :param string  unit:            KPI unit
        :param string  kpi_id:          KPI ID - id of KPI in format '00001'.
        :param string  variant:         KPI variant(in JSON format) - In most cases it is product name of device
                                        involved for particular KPI.
                At this moment ReP support following keys:
                variant = {
                        "bbmod": ["ABIA"],  # LIst of BBMODs, e.g.: which BBMOD was restarted
                        "smod": ["ASIK"],   # List of SMODs, e.g.: which SMOD was restarted
                        "rmod": ["APHG"],   # List of RMODs, e.g.: which RMOD was restarted
                        "rat": ["5G"],      # List of used RAT, eg for lock/unlock
                        "hwf": True         # True/False applicable only for KPI1a
                    }
                All of above keys are not required(fulfil only this param which is applicable to KPI)
        :param string  source:          KPI source e.g.: OAMKPI
        :param string  entity_id:       entity ID e.g.: MRBTS-1
        :param string  comparison_operator: Comparison operator for KPI value.
                       Supported values: '>', '>=', '<', '<=',  '==', '!='
                       Applicable  only for dynamically typed KPIs.
                       If not provided then default ReP KPI comparison operator is used ('<=')

        .. note::
            KPI results are not reported immediately.
            KPI results will be read by ``ute_reporting_portal`` script and added to the Robot report.
        """

        def all_values_are_not_none(param_list):
            for param in param_list:
                if param is None:
                    return False
            return True

        dynamically_typed_kpi_required_params = [
            target,
            name,
            visible_to_db,
            value,
            kpi_type,
            description,
            category,
        ]
        source_based_kpi_required_params = [kpi_id, value, source]

        supported_comparison_operator = {">", ">=", "<", "<=", "==", "!="}
        if (
            comparison_operator
            and comparison_operator not in supported_comparison_operator
        ):
            raise ValueError(
                "Wrong 'comparison_operator' value. "
                f"The value should be one of {supported_comparison_operator}"
                f"but it is '{comparison_operator}'"
            )

        if all_values_are_not_none(dynamically_typed_kpi_required_params):
            self._report_dynamically_typed_kpi(
                target,
                name,
                visible_to_db,
                value,
                kpi_type,
                description,
                category,
                unit,
                entity_id,
                comparison_operator,
            )
        elif all_values_are_not_none(source_based_kpi_required_params):
            if comparison_operator:
                logging.warning(
                    "Comparison operator is not applicable for source based KPIs and will be ignored."
                )
            self._report_source_based_kpi(
                kpi_id, value, source, target, variant, entity_id
            )
        else:
            param_set_1 = (
                "target, name, visible_to_db, value, kpi_type, description, category, "
                "unit, entity_id, comparison_operator"
            )
            param_set_2 = "kpi_id, value, target, variant, source, entity_id"
            raise WrongParameterSet(
                f"Wrong Set of Parameters. Supported sets: \n{param_set_1}\nor\n{param_set_2}"
            )

    def _report_dynamically_typed_kpi(
            self,
            target,
            name,
            visible_to_db,
            value,
            kpi_type,
            description,
            category,
            unit,
            entity_id=None,
            comparison_operator=None
    ) -> None:

        """Keyword to report kpi results.

        :param string  target:          KPI target
        :param string  name:            KPI name
        :param string  visible_to_db:   defines visibility for db
        :param string  value:           KPI value
        :param string  kpi_type:        KPI type
        :param string  description:     KPI description
        :param string  category:        KPI category
        :param string  unit:            KPI unit
        :param string  entity_id:       entity ID e.g.: MRBTS-1
        :param string  comparison_operator: Comparison operator for KPI value.
                       Supported values: '>', '>=', '<', '<=',  '==', '!='
                       If not provided then default ReP KPI comparison operator is used ('<=')

        .. note::
            KPI results are not reported immediately.
            KPI results will be read by ``ute_reporting_portal`` script and added to the Robot report.
        """
        for param in (
            target,
            name,
            visible_to_db,
            value,
            kpi_type,
            description,
            category,
            unit,
        ):
            if not isinstance(param, str):
                raise WrongDataFormat(
                    f"Wrong '{param}' format. The format should be string, not {type(param)}"
                )
        message = (
            f"Reported KPI results: TARGET={target}, NAME={name}, VISIBLE_TO_DB={visible_to_db}, "
            f"VALUE={value}, KPI_TYPE={kpi_type}, DESCRIPTION={description}, "
            f"CATEGORY={category}, UNIT={unit}"
        )

        optional_params = [
            ("entity_id", entity_id),
            ("comparison_operator", comparison_operator),
        ]
        for name, value in optional_params:
            if value:
                message = message + f", {name.upper()}={value}"

        logger.info(message)

    def _report_source_based_kpi(  # noqa: C901
            self,
            kpi_id,
            value,
            source,
            target: Optional[str] = None,
            variant: Optional[str] = None,
            entity_id: Optional[str] = None,
    ) -> None:
        """Keyword to report kpi defined in external source table.

        :param string  kpi_id:      KPI ID
        :param string  value:       KPI value
        :param string  target:      KPI target
        :param string  variant:     KPI variant
        :param string  source:      KPI source, e.g. OAMKPI
        :param string  entity_id:   entity ID, e.g. MRBTS-1


        .. note::
            KPI results are not reported immediately.
            KPI results will be read by ``ute_reporting_portal`` script and added to the Robot report.
        """
        string_based_params = [kpi_id, value, source]
        if target:
            string_based_params.append(target)

        if variant:
            try:
                json.loads(variant)
            except (TypeError, ValueError, JSONDecodeError):
                raise WrongDataFormat(
                    f"Wrong 'variant' value format {variant} - The format should be a JSON string"
                )

        for param in string_based_params:
            if not isinstance(param, str):
                raise WrongDataFormat(
                    f"Wrong '{param}' format. The format should be string, not {type(param)}"
                )

        defined_params = []
        all_params = [
            ("id", kpi_id),
            ("value", value),
            ("source", source),
            ("target", target),
            ("variant", variant),
            ("entity_id", entity_id),
        ]

        for name, value in all_params:
            if value is not None:
                defined_params.append(f"{name.upper()}={value}")

        message = f"Reported KPI results: {', '.join(defined_params)}"
        logger.info(message)

    def add_to_test_data(self, data: str) -> None:
        """Put extra data to test_data dict.

        :param string  data:          JSON dumped data

        .. note::
            This keyword adds the provided data to Robot's ``output.xml`` file which is then
            used by ``ute_reporting_portal`` script to prepare the report and send it to ReP.
        """

        def convert_from_string(data_string):
            try:
                data_string = (
                    data_string.decode(encoding="utf-8")
                    if isinstance(data_string, bytes)
                    else str(data_string)
                )
                return ast.literal_eval(data_string)
            except ValueError:
                raise WrongDataFormat(exc_msg.format(type(data)))

        exc_msg = ("Wrong data format. The format should be either "
                   "dict or a string representation of dict, not {}")

        if isinstance(data, str):
            data = convert_from_string(data)

        if not isinstance(data, dict):
            raise WrongDataFormat(exc_msg.format(type(data)))

        logger.info(f"Extra data for test: DATA={json.dumps(data)}")

    def add_snapshot_link_to_report(self, relative_path: str, description: str) -> None:
        """
        Add snapshot link to report.

        .. note::
            Currently it's working properly only with Linux filesystem

        :param relative_path: path to snapshot(relative to  ${OUTPUT DIR} Robot variable)
        :param description: free text - additional info about from which BTS, phase of test, etc.
        :return: None
        :raises:
            WrongDataFormat: when provided params are not string
            FileDoesNotExist: when provided relative path not exists(relative to ${OUTPUT DIR} Robot variable)
        """
        self._add_symptom_logs_link_to_report(
            relative_path, description, log_type="SNAPSHOT"
        )

    def add_syslog_link_to_report(self, relative_path: str, description: str) -> None:
        """
        Add syslog link to report.

        .. note::
            Currently it's working properly only with Linux filesystem

        :param relative_path: path to syslog(relative to  ${OUTPUT DIR} Robot variable)
        :param description: free text - here could be provided more information about from which BTS, phase of test etc
        :return: None
        :raises:
            WrongDataFormat: when provided params are not string
            FileDoesNotExist: when provided relative path not exists(relative to ${OUTPUT DIR} Robot variable)
        """
        self._add_symptom_logs_link_to_report(
            relative_path, description, log_type="SYSLOG"
        )

    def _add_symptom_logs_link_to_report(self, relative_path, description, log_type):
        if not isinstance(relative_path, str):
            raise WrongDataFormat(
                "Wrong 'relative_path' format. "
                f"The format should be string, not {type(relative_path)}"
            )
        if not isinstance(description, str):
            raise WrongDataFormat(
                "Wrong 'description' format. "
                f"The format should be string, not {type(description)}"
            )

        absolute_path = os.path.join(
            BuiltIn().get_variable_value("${OUTPUT_DIR}"), relative_path
        )
        if not os.path.isfile(absolute_path):
            raise FileDoesNotExist(
                f"Provided 'relative_path': '{relative_path}' does not exist at '{absolute_path}'"
            )

        logger.info(
            f"Add {log_type.upper()} path location: RELATIVE_PATH={relative_path}, DESCRIPTION={description}"
        )

    def add_bts_to_report(
            self,
            mrbts_id: str,
            build: str,
            role: Optional[str] = None,
            scout_scf_id: Optional[str] = None
    ) -> None:
        """Keyword to add BTS to report.

        :param string mrbts_id:         BTS ID e.g.: MRBTS-1
        :param string build:            BTS build e.g.: SBTS23R3_ENB_0000_001563_000000
        :param string role:             BTS role e.g.: SA/NSA/SA+NSA - based on gNBCuType parameter
                                        More details: https://nidd-prod1.ext.net.nokia.com/NIDD/CM/Parameter
                                        /ViewEdit/1808381?vId=1&pId=80884&crntPkgId=80884#/back
        :param string scout_scf_id:     BTS scout scf id
        :return: None
        :raises:
            ValueError: when role is not SA or NSA or SA+NSA
            ValueError: when value contains ', '
        """
        supported_bts_roles = {"SA", "NSA", "SA+NSA"}
        if role and role not in supported_bts_roles:
            raise ValueError(
                f"Wrong 'role' value. The value should be one of {supported_bts_roles}, but it is '{role}'"
            )

        self._add_sytem_under_test_to_report(
            sut_type="BTS",
            sut_id=mrbts_id,
            list_of_params=[
                ("build", build),
                ("role", role),
                ("scout_scf_id", scout_scf_id),
            ],
        )

    def _add_sytem_under_test_to_report(self, sut_type: str, sut_id: str, list_of_params: list) -> None:
        """Keyword to add SUT to report.

        :param string sut_type:         System Under Test type, e.g.: BTS.
        :param string sut_id:           SUT ID e.g.: MRBTS-1
        :return: None
        :raises: ValueError: when value contains ', '
        """
        defined_params = []
        for name, value in list_of_params:
            if value is not None:
                if ", " in str(value):
                    raise ValueError(
                        f"Wrong '{name}' value. The value should not contain ', '"
                    )
                defined_params.append(f"{name.upper()}={value}")

        self._check_if_sut_id_already_reported(sut_id)
        message = f"Add {sut_type.upper()}: ID={sut_id}, {', '.join(defined_params)}"
        logger.info(message)

    def _check_if_sut_id_already_reported(self, sut_id: str) -> None:
        current_test_name = BuiltIn().get_variable_value("${TEST_NAME}")
        test_id = self._get_unique_robot_test_identifier()

        if test_id not in reporting_portal.already_reported_sut:
            reporting_portal.already_reported_sut[test_id] = set()

        if sut_id in reporting_portal.already_reported_sut[test_id]:
            logger.warning(
                f"The SUT identifier '{sut_id}' has already been reported in the test case '{current_test_name}'. "
                "Please note that the previous reported data will be overwritten in the report"
            )

        reporting_portal.already_reported_sut[test_id].add(sut_id)

    def _get_unique_robot_test_identifier(self):
        test = EXECUTION_CONTEXTS.current.test
        return test.id

    def map_testcase(self, testcase_name) -> None:
        """Keyword to map test case name as other one.

        :param string  testcase_name:          test case name to be set in QC report

        .. note::
            Test case name is not set immediately.
            Test case name will be read by ``ute_reporting_portal`` script and set in the Robot report.
        """
        if not isinstance(testcase_name, str):
            raise WrongDataFormat(
                f"Wrong id format. The format should be string, not {type(testcase_name)}"
            )
        test = EXECUTION_CONTEXTS.current.test
        new_tag = f"MAP_TC_{testcase_name}"
        test.tags.add(new_tag)
        logger.info(f"Map Testcase as: {new_tag}")

